import 'package:flutter/foundation.dart'; import '../models/exercise.dart'; import '../repositories/exercise_repository.dart'; class HealthViewModel extends ChangeNotifier { HealthViewModel(this._repository); final ExerciseRepository _repository; String _category='All'; List<Exercise> _exercises=[]; String get selectedCategory=>_category; List<Exercise> get exercises=>_category=='All'?_exercises:_exercises.where((e)=>e.category==_category).toList(); Future<void> load() async{_exercises=await _repository.loadExercises();notifyListeners();} void selectCategory(String value){_category=value;notifyListeners();} }
